// Save generated image
var saveImage = () => {
  const name = getYYYYMMDD_hhmmss(true) + '.png';
  saveCanvas(name, 'png');
};

// get Timestamp string
var getYYYYMMDD_hhmmss = (isNeedUS) => {
  const now = new Date();
  let retVal = '';

  // YYMMDD
  retVal += now.getFullYear();
  retVal += padZero2Digit(now.getMonth() + 1);
  retVal += padZero2Digit(now.getDate());

  if (isNeedUS) {
    retVal += '_';
  }

  // hhmmss
  retVal += padZero2Digit(now.getHours());
  retVal += padZero2Digit(now.getMinutes());
  retVal += padZero2Digit(now.getSeconds());

  return retVal;
};

// padding function
var padZero2Digit = (num) => {
  return (num < 10 ? '0' : '') + num;
};


// === Tab: mySketch ===

var W;

var numCircles = 10;
var circles = [];

function setup() {
  W = Math.min(windowHeight, windowWidth);
  createCanvas(W, W);

  prepareTexture(width, height);

  // Prepare circles
  for (let i = 0; i < numCircles; i++) {
    circles.push({
      x: random(width / 4, (3 * width) / 4),
      y: random(height / 4, (3 * height) / 4),
      r: random(width / 15, width / 4),
      xSpeed: random(1, 2),
      ySpeed: random(1, 2),
      xDir: random([-1, 1]),
      yDir: random([-1, 1]),
    });
  }
}

function draw() {
  background('#06aed5');

  // Draw circles
  const lineStrokeColor = color('#086788');
  lineStrokeColor.setAlpha(map(sin(frameCount / 60), -1, 1, 0, 255));
  stroke(lineStrokeColor);
  strokeWeight(width * 3 / 720);
  noFill();

  circles.forEach((c) => {
    circle(c.x, c.y, 2 * c.r);
  });

  // Draw crossing points
  noStroke();
  fill('#f0c808');

  for (let i = 0; i < circles.length; i++) {
    for (let j = i + 1; j < circles.length; j++) {
      drawCrossPoints(circles[i], circles[j]);
    }
  }

  // update circle info
  updateCircleInfo();

  // Draw texture
  image(textureGfx, 0, 0);
}

var drawCrossPoints = (c1, c2) => {
  var crossPoints = getCirclesCrossPoints(c1.x, c1.y, c1.r, c2.x, c2.y, c2.r);
  // console.log(crossPoints)

  crossPoints.forEach((cp) => {
    circle(cp.x, cp.y, width * 11 / 720);
  });
}

var updateCircleInfo = () => {
  circles.forEach((c) => {
    c.x += c.xSpeed * c.xDir;
    c.y += c.ySpeed * c.yDir;

    // Bounce cases
    if (c.x > width - c.r || c.x < c.r) {
      c.xDir *= -1;
    }
    if (c.y > height - c.r || c.y < c.r) {
      c.yDir *= -1;
    }
  });
};
